// Render an SVG master at w x h pixels (the masters carry their own viewBox).
const sized = (svg, w, h = w) =>
  svg.replace(/^<svg ([^>]*?)width="[^"]*" height="[^"]*"/, `<svg $1width="${w}" height="${h}"`);

async function write(svg, file, w, h = w, opaque = false) {
  mkdirSync(path.dirname(file), { recursive: true });
  const image = sharp(Buffer.from(sized(svg, w, h)));
  await (opaque ? image.flatten({ background: "#0B4A44" }) : image).png().toFile(file);
}

const densities = { mdpi: 1, hdpi: 1.5, xhdpi: 2, xxhdpi: 3, xxxhdpi: 4 };
for (const [name, k] of Object.entries(densities)) {
  await write(LEGACY, `${res}/mipmap-${name}/ic_launcher.png`, 48 * k);
  await write(ROUND, `${res}/mipmap-${name}/ic_launcher_round.png`, 48 * k);
  await write(FOREGROUND, `${res}/mipmap-${name}/ic_launcher_foreground.png`, 108 * k);
  await write(BACKGROUND, `${res}/mipmap-${name}/ic_launcher_background.png`, 108 * k);
  await write(MONOCHROME, `${res}/mipmap-${name}/ic_launcher_monochrome.png`, 108 * k);
  await write(SPLASH_ICON, `${res}/drawable-${name}/splash_icon.png`, 288 * k);
  await write(SPLASH_PORT, `${res}/drawable-port-${name}/splash.png`, 320 * k, 480 * k, true);
  await write(SPLASH_LAND, `${res}/drawable-land-${name}/splash.png`, 480 * k, 320 * k, true);
}
await write(SPLASH_PORT, `${res}/drawable/splash.png`, 480, 720, true);

const xcassets = path.resolve("ios/App/App/Assets.xcassets");
await write(SQUARE, `${xcassets}/AppIcon.appiconset/AppIcon-512@2x.png`, 1024, 1024, true);
for (const name of ["splash-2732x2732", "splash-2732x2732-1", "splash-2732x2732-2"]) {
  await write(SPLASH_SQUARE, `${xcassets}/Splash.imageset/${name}.png`, 2732, 2732, true);
}
// The desktop app's source icon; apps/desktop turns it into every size with `tauri icon`.
await write(LEGACY, path.resolve("../desktop/app-icon.png"), 1024);
console.log("icons written");
